// The Odalo logo is ONE fixed inventory of 14 tiles that forms the lowercase wordmark "odalo." and three symbols.
// Tiles never change geometry, size or colour; only their pose {x, y, r} changes. This file authors the poses;
// logo-plan.js (generated by scripts/mosaic-optimize.mjs) decides which tile takes which slot and when each one moves.
import { PALETTE } from './palette.js';
const C = PALETTE;

/** id, shape, fill. */
export const LOGO_TILES = [
  { id: 'ha1', shape: 'ha', fill: C.navy },  { id: 'ha2', shape: 'ha', fill: C.slate },   // o (first)
  { id: 'ha3', shape: 'ha', fill: C.coral },                                              // d bowl
  { id: 'ha4', shape: 'ha', fill: C.navy },                                               // a bowl
  { id: 'ha5', shape: 'ha', fill: C.navy },  { id: 'ha6', shape: 'ha', fill: C.coral },   // o (second)
  { id: 'sq1', shape: 'sq', fill: C.slate }, { id: 'sq2', shape: 'sq', fill: C.navy },    // d connectors
  { id: 'sq3', shape: 'sq', fill: C.coral }, { id: 'sq4', shape: 'sq', fill: C.navy },    // a connectors
  { id: 'bar1', shape: 'r6', fill: C.navy }, { id: 'bar2', shape: 'r6', fill: C.slate },  // d stem, l
  { id: 'bar3', shape: 'r4', fill: C.navy },                                              // a stem
  { id: 'dot', shape: 'dot', fill: C.coral },
];

const P = (x, y, r = 0) => ({ x, y, r });
const rot2 = (x, y, deg) => { const a = (deg * Math.PI) / 180; return [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)]; };
const r3 = (n) => +n.toFixed(3);
/** An arch whose flat face is centred on (fx,fy) and which bulges towards `deg` (0 = right, -90 = up). */
function arch(out, id, fx, fy, deg) {
  const [ox, oy] = rot2(0, -1, deg + 90); // the arch's own centre is 1u from its flat face, on the bulge side
  out[id] = P(r3(fx + ox), r3(fy + oy), deg + 90);
}
/** A ring from two arches centred on (cx,cy), the pair turned by phi. */
function ring(out, ids, cx, cy, phi = 0) {
  arch(out, ids[0], cx, cy, -90 + phi); arch(out, ids[1], cx, cy, 90 + phi);
}
const put = (out, id, x, y, r = 0) => { out[id] = P(r3(x), r3(y), r); };
const polar = (px, py, rho, deg) => { const [x, y] = rot2(rho, 0, deg); return [px + x, py + y]; };

/** The wordmark. x-height 4u, ascender 6u, stroke 1u, tight letter gap of 0.5u. */
function wordmark() {
  const G = 0.5;
  /** @type {Record<string, any>} */
  const o = {};
  ring(o, ['ha1', 'ha2'], 2, 4);                        // o
  const d = 4 + G;                                      // d starts here
  arch(o, 'ha3', d + 2, 4, 180);                        // left half-ring (bulges left), flat face on the stem side
  put(o, 'sq1', d + 2.5, 2.5); put(o, 'sq2', d + 2.5, 5.5); put(o, 'bar1', d + 3.5, 3);
  const a = d + 4 + G;                                  // a
  arch(o, 'ha4', a + 2, 4, 180);
  put(o, 'sq3', a + 2.5, 2.5); put(o, 'sq4', a + 2.5, 5.5); put(o, 'bar3', a + 3.5, 4);
  const l = a + 4 + G;                                  // l
  put(o, 'bar2', l + 0.5, 3);
  const o2 = l + 1 + G;                                 // second o
  ring(o, ['ha5', 'ha6'], o2 + 2, 4);
  put(o, 'dot', o2 + 4 + G + 0.6, 5.4);
  return o;
}

const IDS = ['ha1', 'ha2', 'ha3', 'ha4', 'ha5', 'ha6'];
/** Bloom: a ring with four arches around it, squares in the notches, bars as a frame, dot at the side. */
function bloom() {
  /** @type {Record<string, any>} */
  const o = {};
  ring(o, [IDS[0], IDS[1]], 0, 0);
  arch(o, IDS[2], 0, -2, -90); arch(o, IDS[3], 2, 0, 0); arch(o, IDS[4], 0, 2, 90); arch(o, IDS[5], -2, 0, 180);
  put(o, 'sq1', -2.5, -2.5); put(o, 'sq2', 2.5, -2.5); put(o, 'sq3', 2.5, 2.5); put(o, 'sq4', -2.5, 2.5);
  put(o, 'bar1', 0, -4.5, 90); put(o, 'bar2', 0, 4.5, 90); put(o, 'bar3', 4.5, 0);
  put(o, 'dot', -4.6, 0);
  return o;
}
/** Windmill: the same arches as a pinwheel around the ring; every arch stands flat on a side of the ring's square. */
function windmill() {
  /** @type {Record<string, any>} */
  const o = {};
  ring(o, [IDS[0], IDS[1]], 0, 0);
  arch(o, IDS[2], 2, -2, -90);  // top arch, spans x 0..4
  arch(o, IDS[3], 2, 2, 0);     // right arch, spans y 0..4
  arch(o, IDS[4], -2, 2, 90);   // bottom arch, spans x -4..0
  arch(o, IDS[5], -2, -2, 180); // left arch, spans y -4..0
  put(o, 'sq1', 2.5, -1.5); put(o, 'sq2', 1.5, 2.5); put(o, 'sq3', -2.5, 1.5); put(o, 'sq4', -1.5, -2.5);
  put(o, 'bar1', 0, -4.5, 90); put(o, 'bar2', 0, 4.5, 90); put(o, 'bar3', 4.5, 0);
  put(o, 'dot', -4.6, 0);
  return o;
}
/** Trefoil: three tangent rings (the dot is the eye of the top one) on a single stripe, a stem to the side. */
function trefoil() {
  /** @type {Record<string, any>} */
  const o = {};
  ring(o, [IDS[0], IDS[1]], -2, 1); ring(o, [IDS[4], IDS[5]], 2, 1); ring(o, [IDS[2], IDS[3]], 0, 1 - 2 * Math.sqrt(3));
  put(o, 'bar1', -1, 3.5, 90); put(o, 'sq1', 2.5, 3.5); put(o, 'sq2', 3.5, 3.5);
  put(o, 'bar2', 0, 4.5, 90); put(o, 'sq3', 3.5, 4.5); put(o, 'sq4', 4.5, 4.5);
  put(o, 'bar3', 4.5, 1); put(o, 'dot', 0, 1 - 2 * Math.sqrt(3));
  return o;
}

/** Hand-authored poses, before the optimiser's slot permutation. */
export const LOGO_RAW = { bloom: bloom(), windmill: windmill(), trefoil: trefoil(), wordmark: wordmark() };
/** The three symbols, in the order the header shows them. */
export const LOGO_SYMBOLS = ['bloom', 'windmill', 'trefoil'];
/** One shared viewBox: the wordmark (6u tall) and every symbol fit in it, so the logo never changes size. */
export const LOGO_VIEWBOX = { w: 24, h: 11 };

const EXT = { ha: [4, 2], sq: [1, 1], r6: [1, 6], r4: [1, 4], dot: [1.2, 1.2] };
function bounds(arr) {
  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
  for (const t of LOGO_TILES) {
    const p = arr[t.id], [w, h] = EXT[t.shape], a = (p.r * Math.PI) / 180;
    const hx = (Math.abs(Math.cos(a)) * w + Math.abs(Math.sin(a)) * h) / 2, hy = (Math.abs(Math.sin(a)) * w + Math.abs(Math.cos(a)) * h) / 2;
    x0 = Math.min(x0, p.x - hx); x1 = Math.max(x1, p.x + hx); y0 = Math.min(y0, p.y - hy); y1 = Math.max(y1, p.y + hy);
  }
  return { x0, y0, x1, y1 };
}
/** Translate an arrangement so its bounds are centred in the logo viewBox. */
export function centred(arr) {
  const b = bounds(arr), dx = LOGO_VIEWBOX.w / 2 - (b.x0 + b.x1) / 2, dy = LOGO_VIEWBOX.h / 2 - (b.y0 + b.y1) / 2;
  return Object.fromEntries(Object.entries(arr).map(([id, p]) => [id, { x: r3(p.x + dx), y: r3(p.y + dy), r: p.r }]));
}
